import wasmUrl from './nrx-runtime.wasm?url';
import {createRuntime,NRX_WASM_SHA256} from './runtime.mjs';
import {prepareField,recordsToModel} from './scalar.mjs';
const hash=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');
self.onmessage=async({data})=>{try{const start=performance.now(),mask=new Uint8Array(data.mask);const maskSha256=await hash(mask);if(maskSha256!=='18c8b7f2cf420d26ecb2f3f052016d4cd97c91773e497e36a434098cd47377c3')throw Error('NRX adapter accepts only the admitted public H000 SEG');
 const prepared=prepareField(mask,data.count);const scalarSha256=await hash(prepared.field);const response=await fetch(wasmUrl);if(!response.ok)throw Error('NRX adapter unavailable');const runtime=await createRuntime(await response.arrayBuffer());const extracted=runtime.extract(prepared.field,prepared.size,prepared.origin);const recordSha256=await hash(extracted.records);const result=recordsToModel(extracted.records,data.matrices);const positionSha256=await hash(result.positions);
 self.postMessage({positions:result.positions.buffer,provenance:{method:'NRX/R002 dense occupancy extraction in isolated wasm32 worker; separable [1,2,1]/4 index-space smoothing, isovalue 0.5; explicit winding reversal in model space',representation:'NRX SEG display derivative',semanticId:'lesion.lung.mass.001',segment:1,sourceVoxels:prepared.count,gridSize:prepared.size,originKRowColumn:prepared.origin,triangles:result.triangles,maskSha256,scalarSha256,recordSha256,positionSha256,wasmSha256:NRX_WASM_SHA256,wasmCapacityBytes:extracted.wasmCapacityBytes,winding:{correction:'swap triangle vertices 1 and 2',before:result.signedBefore,after:result.signedAfter},generationMs:performance.now()-start,limitation:'Display derivative; thin features can disappear. No organ segmentation, clinical accuracy, or production NRX ABI claim.'}},[result.positions.buffer]);
 }catch(error){self.postMessage({error:error.message})}};
